{
  "doc_summary": "通过约伯记1章1-8节，讲员阐述约伯的绝对稳固与天上场景的对比，纠正将环境顺遂等同于上帝认可的信仰误区，强调真正的智慧是认识耶和华并持守纯正。",
  "chapters": [
    {
      "title": "约伯的现实背景：绝对稳固的人生",
      "sections": [
        {
          "title": "约伯的财富与地位",
          "paragraphs": [
            {
              "start": 1,
              "end": 5,
              "summary": "讲员开场问候，表示要宣读约伯记一章1-8节经文，并解释难解部分。",
              "keywords": ["约伯记", "经文宣读"],
              "cue": "开场白与经文引入"
            },
            {
              "start": 6,
              "end": 25,
              "summary": "诵读约伯记1:1-8节，描述约伯的完全正直、家庭财富、献祭习惯以及天上撒旦的出现。",
              "keywords": ["约伯", "完全正直", "献燔祭", "撒旦"],
              "cue": "诵读经文"
            },
            {
              "start": 26,
              "end": 33,
              "summary": "讲员带领祷告，求神开启会众耳朵，赐予真知识。",
              "keywords": ["祷告", "神的话语"],
              "cue": "祷告环节"
            },
            {
              "start": 34,
              "end": 48,
              "summary": "讲员介绍讲道大纲：分两部分，1-5节看约伯的现实背景，6-8节看属灵背景。",
              "keywords": ["大纲", "现实背景", "属灵背景"],
              "cue": "讲道结构说明"
            },
            {
              "start": 49,
              "end": 54,
              "summary": "讲员自我介绍，说明服侍任务，并计划用约伯记开始系列讲道。",
              "keywords": ["自我介绍", "服侍任务", "约伯记"],
              "cue": "自我介绍与服侍计划"
            },
            {
              "start": 55,
              "end": 63,
              "summary": "讲员指出教会信仰过于关注个人祸福，约伯记能预备智慧，挑战传统观念。",
              "keywords": ["信仰关注", "约伯记", "智慧"],
              "cue": "从个人服侍转入信仰现状"
            },
            {
              "start": 64,
              "end": 79,
              "summary": "讲员强调约伯记是智慧书第一卷，主题是认识耶和华的智慧，并提出两个问题：绝对平安是否存在，上帝认可的信仰是否远离灾祸。",
              "keywords": ["约伯记", "智慧", "绝对平安", "灾祸"],
              "cue": "提出讲道核心问题"
            }
          ]
        },
        {
          "title": "约伯的稳固：从道德到经济",
          "paragraphs": [
            {
              "start": 80,
              "end": 87,
              "summary": "讲员介绍约伯记成书最早，约伯生活在亚伯拉罕之前，是古代圣徒。",
              "keywords": ["约伯记", "成书时间", "亚伯拉罕"],
              "cue": "背景介绍"
            },
            {
              "start": 88,
              "end": 114,
              "summary": "讲员解释约伯不是以色列人，但耶和华是全地的主，独一神信仰早于摩西，该隐和麦基洗德都认识神。",
              "keywords": ["约伯", "乌斯地", "独一神信仰", "麦基洗德"],
              "cue": "解释约伯身份与信仰背景"
            },
            {
              "start": 115,
              "end": 140,
              "summary": "讲员提问为何圣经记录约伯的情况，指出1-5节突出约伯的稳固，与后面灾难形成落差。",
              "keywords": ["约伯", "稳固", "落差"],
              "cue": "从背景转向经文意义"
            },
            {
              "start": 141,
              "end": 174,
              "summary": "讲员讨论人们通常认为的平安因素：财富、健康、保险等，并指出恶人常遭恶报，但约伯并非如此。",
              "keywords": ["平安", "抗风险能力", "恶有恶报"],
              "cue": "从经文转向现实讨论"
            },
            {
              "start": 175,
              "end": 211,
              "summary": "讲员分析约伯的完全正直和敬畏神，排除道德、法律、信仰上的风险因素，强调约伯无懈可击。",
              "keywords": ["约伯", "完全正直", "敬畏神", "风险排除"],
              "cue": "解经约伯记1:1"
            },
            {
              "start": 212,
              "end": 237,
              "summary": "讲员讨论约伯的家庭和财富，强调人丁兴旺和财富是抗风险因素，约伯的财富和地位在东方为至大。",
              "keywords": ["约伯", "家庭", "财富", "东方为至大"],
              "cue": "解经约伯记1:2-3"
            },
            {
              "start": 238,
              "end": 267,
              "summary": "讲员解释约伯的财富：7000只羊、3000骆驼、500对牛等，说明其牧场、物流、农业规模庞大。",
              "keywords": ["约伯", "财富", "羊", "骆驼", "牛"],
              "cue": "解释约伯的财富细节"
            },
            {
              "start": 268,
              "end": 280,
              "summary": "讲员强调约伯在东方为至大，其强盛程度堪比君王，但后来却坐在炉灰中。",
              "keywords": ["约伯", "东方为至大", "强盛", "炉灰"],
              "cue": "总结约伯的财富与地位"
            }
          ]
        },
        {
          "title": "约伯的家庭与信仰教育",
          "paragraphs": [
            {
              "start": 281,
              "end": 303,
              "summary": "讲员总结约伯的经济富可敌国，地位东方为至大，认为这类人不会遇到风险。",
              "keywords": ["约伯", "经济", "地位", "风险"],
              "cue": "总结约伯的素描"
            },
            {
              "start": 304,
              "end": 323,
              "summary": "讲员反驳豪门家庭有争端的观点，引用约伯记1:4说明约伯儿女和睦，家庭其乐融融。",
              "keywords": ["约伯", "家庭和睦", "儿女聚餐"],
              "cue": "解经约伯记1:4"
            },
            {
              "start": 324,
              "end": 353,
              "summary": "讲员强调约伯对儿女的信仰教育顶级，常献燔祭，怕儿女弃掉神，家庭在圣约看守中。",
              "keywords": ["约伯", "信仰教育", "献燔祭", "圣约"],
              "cue": "解经约伯记1:5"
            }
          ]
        },
        {
          "title": "约伯的稳固与灾难的落差",
          "paragraphs": [
            {
              "start": 354,
              "end": 379,
              "summary": "讲员强调约伯记的冲击力：如此稳固的家庭后来家破人亡，且允许此事的是耶和华。",
              "keywords": ["约伯", "冲击力", "家破人亡", "耶和华"],
              "cue": "从稳固转向灾难"
            },
            {
              "start": 380,
              "end": 410,
              "summary": "讲员指出约伯记的智慧是倒掉虚假平安，认识到人生安稳的支柱可能瞬间倒塌，真正看守的是耶和华的篱笆。",
              "keywords": ["约伯记", "智慧", "虚假平安", "耶和华的篱笆"],
              "cue": "从解经转向应用"
            },
            {
              "start": 411,
              "end": 427,
              "summary": "讲员解释身外之物与身内之物的失去，最终剩下的是敬畏耶和华的真知识，神要收割果子。",
              "keywords": ["身外之物", "身内之物", "真知识", "收割"],
              "cue": "继续应用"
            },
            {
              "start": 428,
              "end": 444,
              "summary": "讲员强调正确的预设和期待，避免错误期待导致去掉或更改福音，持守纯正如约伯。",
              "keywords": ["预设", "期待", "持守纯正", "约伯"],
              "cue": "从应用转向劝勉"
            }
          ]
        },
        {
          "title": "从神手里得福与受祸",
          "paragraphs": [
            {
              "start": 445,
              "end": 477,
              "summary": "讲员回应常见说法，引用约伯记2:9，强调从神手里得福也受祸，并解释约伯妻子的崩溃。",
              "keywords": ["约伯记2:9", "得福受祸", "约伯妻子"],
              "cue": "引入约伯记2章"
            },
            {
              "start": 478,
              "end": 511,
              "summary": "讲员引用罗马书8:28，解释万事互相效力，为救恩益处，强调永恒福乐与暂存祸福的对比。",
              "keywords": ["罗马书8:28", "万事互相效力", "永恒福乐"],
              "cue": "引用罗马书"
            },
            {
              "start": 512,
              "end": 546,
              "summary": "讲员区分两套福音：只给福的福音与祸福都为救恩效力的福音，强调后者是真实的。",
              "keywords": ["两套福音", "救恩", "祸福"],
              "cue": "从应用转向教义"
            }
          ]
        }
      ]
    },
    {
      "title": "约伯的属灵背景：天上的场景",
      "sections": [
        {
          "title": "天上的集会与撒旦的出现",
          "paragraphs": [
            {
              "start": 547,
              "end": 557,
              "summary": "讲员总结1-5节，强调约伯的稳固，但指出这些支架会失去，最终看守的是耶和华的篱笆。",
              "keywords": ["约伯", "稳固", "篱笆"],
              "cue": "总结第一部分"
            },
            {
              "start": 558,
              "end": 570,
              "summary": "讲员转向第二部分，指出影响家庭的是天上的场景，而非银行里的保障。",
              "keywords": ["天上场景", "影响家庭"],
              "cue": "过渡到第二部分"
            },
            {
              "start": 571,
              "end": 604,
              "summary": "讲员解释神的众子指天使，撒旦也在其中，但已不是神的众子，暗示其不协调。",
              "keywords": ["神的众子", "撒旦", "天使"],
              "cue": "解经约伯记1:6"
            },
            {
              "start": 605,
              "end": 646,
              "summary": "讲员解释耶和华询问撒旦是授权，而非困惑，撒旦在上帝权下，不能主动发言。",
              "keywords": ["耶和华", "撒旦", "授权"],
              "cue": "解经约伯记1:7"
            },
            {
              "start": 647,
              "end": 660,
              "summary": "讲员强调撒旦受上帝权柄限制，神的儿女在困境中也能安稳，因为上帝掌控。",
              "keywords": ["撒旦", "权柄", "困境"],
              "cue": "从解经转向应用"
            }
          ]
        },
        {
          "title": "撒旦的有限性与约伯的受试炼",
          "paragraphs": [
            {
              "start": 661,
              "end": 677,
              "summary": "讲员提出两个选择题：耶和华主动引撒旦注意约伯，还是撒旦本来就在关注约伯，并准备用证据说明。",
              "keywords": ["耶和华", "撒旦", "约伯"],
              "cue": "引入问题"
            },
            {
              "start": 678,
              "end": 730,
              "summary": "讲员论证撒旦不是全知全能，受空间限制，需要走来走去，因此撒旦一直在约伯身边。",
              "keywords": ["撒旦", "空间限制", "全知"],
              "cue": "论证撒旦的有限性"
            },
            {
              "start": 731,
              "end": 775,
              "summary": "讲员指出撒旦对约伯的评估两次出错，而上帝全知无误，撒旦需要观察人，上帝却从开始就了解。",
              "keywords": ["撒旦", "评估出错", "上帝全知"],
              "cue": "从撒旦有限性转向上帝全知"
            }
          ]
        },
        {
          "title": "义人受苦与恶人亨通",
          "paragraphs": [
            {
              "start": 776,
              "end": 793,
              "summary": "讲员强调上帝允许约伯受祸，但撒旦的试探被限制，并指出义人受苦、恶人亨通的主题。",
              "keywords": ["约伯", "受祸", "义人受苦"],
              "cue": "从上帝允许转向主题"
            },
            {
              "start": 794,
              "end": 813,
              "summary": "讲员指出宗教以灵验为招牌，但圣经记载约伯家破人亡，强调不可废去之福。",
              "keywords": ["宗教", "灵验", "不可废去之福"],
              "cue": "从主题转向应用"
            },
            {
              "start": 814,
              "end": 849,
              "summary": "讲员引用中国俗语，强调不能因灾难怀疑信仰，也不能因顺遂认可信仰，环境不是信仰的参考。",
              "keywords": ["好人不长命", "环境", "信仰"],
              "cue": "从应用转向应用"
            }
          ]
        },
        {
          "title": "环境不是信仰的参考",
          "paragraphs": [
            {
              "start": 850,
              "end": 889,
              "summary": "讲员举例说明同一事件有两种解释，强调不要随私意解读环境，环境不是第一参考标准。",
              "keywords": ["环境", "解读", "私意"],
              "cue": "从应用转向应用"
            },
            {
              "start": 890,
              "end": 918,
              "summary": "讲员劝勉不要做属灵的懂王，不要随意解读他人遭遇，约伯的三个朋友就是反面例子。",
              "keywords": ["属灵懂王", "约伯朋友"],
              "cue": "从应用转向劝勉"
            },
            {
              "start": 919,
              "end": 939,
              "summary": "讲员强调智慧书的智慧能装载新酒，不靠环境，而靠上帝圣言作为行动准则。",
              "keywords": ["智慧", "圣言", "准则"],
              "cue": "从劝勉转向总结"
            }
          ]
        },
        {
          "title": "上帝作为的显明",
          "paragraphs": [
            {
              "start": 940,
              "end": 967,
              "summary": "讲员引用约翰福音9:1-3，说明瞎眼与罪无关，而是为显明神的作为，提醒不要限定上帝的回答。",
              "keywords": ["约翰福音9章", "瞎眼", "神的作为"],
              "cue": "引用经文结束"
            },
            {
              "start": 968,
              "end": 969,
              "summary": "讲员以祷告结束，求神引导会众开始看约伯记。",
              "keywords": ["祷告", "约伯记"],
              "cue": "结束祷告"
            }
          ]
        }
      ]
    }
  ]
}
